@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#f5f2ff;--muted:#a19fb8;--bg:#111120;--panel:#1b1b2d;--line:#34334c;--violet:#a386ff;--cyan:#69e4e6;--pink:#ff77bd;--orange:#ffab65}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--ink);font-family:'Space Grotesk',system-ui,sans-serif}body{background-image:radial-gradient(ellipse at 65% 10%,#282044 0,transparent 37%),radial-gradient(ellipse at 10% 70%,#181b35 0,transparent 38%);overflow-x:hidden}.app{width:min(1360px,100%);min-height:100vh;margin:auto;padding:0 6.5%;display:flex;flex-direction:column}.topbar{height:80px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff12}.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none;font-size:14px;font-weight:700;letter-spacing:.13em}.brand i{font-style:normal;color:var(--violet);font-size:10px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;background:var(--violet);color:#171321;border-radius:11px;font-size:14px;letter-spacing:-.08em;transform:rotate(-5deg)}button,select{font:inherit;color:inherit;cursor:pointer}.icon-btn,.pause-btn{border:1px solid var(--line);background:#201f32;border-radius:12px;color:#c8c0e8;width:42px;height:42px;font-size:21px}.menu-screen{flex:1;display:grid;grid-template-columns:1fr .9fr;column-gap:4%;align-content:start}.hero-copy{padding:75px 0 25px;z-index:1}.eyebrow,.section-title small,.pick-title small{font:500 10px 'DM Mono',monospace;letter-spacing:.18em;color:var(--cyan)}h1{font-size:clamp(38px,5.1vw,67px);line-height:.98;letter-spacing:-.065em;margin:19px 0 19px;font-weight:700}h1 span{color:var(--violet)}.intro{max-width:430px;color:#b8b6c8;font-size:15px;line-height:1.65;margin-bottom:27px}.hero-actions{display:flex;gap:12px}.primary,.secondary{padding:14px 20px;border:0;border-radius:11px;font-size:12px;font-weight:700;letter-spacing:.05em;transition:.18s transform,.18s filter}.primary{background:var(--violet);color:#171326;box-shadow:0 7px 22px #8f70ff35}.primary:hover,.secondary:hover,.mode-card:hover{transform:translateY(-2px);filter:brightness(1.12)}.secondary{background:#242237;color:#f4efff;border:1px solid #393650}.mini-tags{display:flex;gap:18px;margin-top:27px;color:#9290a9;font:9px 'DM Mono',monospace;letter-spacing:.08em}.hero-art{position:relative;height:360px;align-self:center;overflow:hidden;background:linear-gradient(145deg,#282341aa,#191a2d88);border:1px solid #ffffff12;border-radius:30px;box-shadow:inset 0 0 70px #765dd31c}.hero-art:after{content:'';position:absolute;inset:auto 0 0;height:35%;background:linear-gradient(transparent,#10111f)}.orbit{position:absolute;border:1px solid #ab91ff35;border-radius:50%;width:310px;height:310px;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-24deg)}.orbit-a{width:360px;height:190px}.orbit-b{transform:translate(-50%,-50%) rotate(53deg);width:240px;height:350px}.hero-vs{position:absolute;z-index:2;left:48%;top:43%;font-size:18px;font-weight:700;color:var(--pink);text-shadow:0 0 19px #ff77bd}.hero-char{position:absolute;z-index:2;bottom:30px;width:140px;height:230px;text-align:center}.hero-char b{display:block;margin-top:8px;font:10px 'DM Mono';letter-spacing:.15em}.lup-hero{left:16%;transform:rotate(-4deg)}.calm-hero{right:11%;transform:rotate(4deg)}.char-head{position:relative;width:100px;height:101px;margin:auto;background:#55bfe2;border:5px solid #171824;border-radius:44% 48% 42% 42%;box-shadow:7px 7px 0 #382f52;z-index:2}.calm-hero .char-head{background:#ffbc83}.mask{position:absolute;left:11px;right:11px;top:31px;height:35px;background:#1a2030;border:3px solid #d5faff;border-radius:13px 13px 19px 19px}.calm-hero .mask{border-color:#ffe6d4}.char-body{width:82px;height:102px;margin:-3px auto 0;background:#75d7ed;border:5px solid #171824;border-radius:23px 23px 12px 12px;transform:rotate(-3deg)}.calm-hero .char-body{background:#f28c4c;transform:rotate(3deg)}.char-leg{position:absolute;bottom:25px;left:32px;width:28px;height:45px;background:#62c5e0;border:4px solid #171824;border-radius:8px;transform:rotate(5deg)}.calm-hero .char-leg{left:76px;background:#f28c4c;transform:rotate(-5deg)}.spark{position:absolute;color:var(--cyan);font-size:23px}.s1{top:22%;left:19%}.s2{right:15%;top:30%;color:var(--pink)}.s3{left:50%;bottom:16%;color:var(--violet)}.menu-lower{grid-column:1/3;padding:24px 0 40px;border-top:1px solid #ffffff12}.section-title{display:flex;align-items:end;justify-content:space-between;margin-bottom:16px}.section-title h2{font-size:20px;margin:6px 0 0;letter-spacing:-.04em}.text-btn{border:0;background:none;color:#bcb0eb;font-size:10px;letter-spacing:.08em}.mode-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.mode-card{display:flex;align-items:center;gap:13px;text-align:left;background:#1b1b2c;border:1px solid #ffffff12;border-radius:14px;padding:15px;transition:.18s}.mode-icon{display:grid;place-items:center;width:39px;height:39px;border-radius:12px;background:#3a3158;color:#c4adff;font-size:18px}.mode-icon.mint{background:#203c42;color:var(--cyan)}.mode-icon.pink{background:#462b43;color:var(--pink)}.mode-card span:nth-child(2){display:grid;gap:4px}.mode-card b{font-size:13px}.mode-card small{font-size:10px;color:#9694ab}.mode-card>i{margin-left:auto;color:#aaa1c5;font-style:normal}.foot{height:48px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid #ffffff10;color:#79788f;font:9px 'DM Mono';letter-spacing:.09em}.foot b{color:var(--cyan)}.hidden{display:none!important}
/* Character select */
.setup-screen{flex:1;padding:34px 0 38px}.setup-head{display:flex;align-items:center;gap:25px;margin-bottom:26px}.setup-head h1{font-size:38px;margin:5px 0 0}.back-btn{border:1px solid var(--line);border-radius:9px;padding:10px 13px;background:#1b1b2b;font:10px 'DM Mono';color:#cac3df}.mode-pill{margin-left:auto;border:1px solid #51466e;color:#bdaaff;background:#241f38;border-radius:30px;padding:9px 13px;font:9px 'DM Mono';letter-spacing:.1em}.setup-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pick-panel{background:#191929;border:1px solid #ffffff12;border-radius:16px;padding:17px}.pick-title{display:flex;align-items:center;gap:11px;margin-bottom:14px}.pick-title h2{font-size:16px;margin:3px 0 0}.pick-title small{color:#aaa2c5}.step{display:grid;place-items:center;background:#34304a;color:#c2b1ff;border-radius:10px;width:36px;height:36px;font:12px 'DM Mono'}.step.opponent{color:#ffabd0;background:#41283c}.roster{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-height:274px;overflow:auto;padding-right:3px}.roster-card{min-height:98px;border:1px solid #ffffff10;border-radius:11px;background:#222236;padding:9px 6px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;transition:.15s}.roster-card.selected{border-color:var(--violet);background:#342d4a;box-shadow:0 0 0 1px #a386ff55}.opponent-roster .roster-card.selected{border-color:var(--pink);box-shadow:0 0 0 1px #ff77bd55}.mini-avatar{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:var(--avatar,#555);font-size:19px;border:2px solid #ffffff2a;box-shadow:0 4px 0 #10101a}.roster-card b{font-size:10px}.roster-card small{font:8px 'DM Mono';color:#9996ad}.setup-footer{display:flex;align-items:end;gap:13px;margin-top:19px}.select-wrap{display:grid;gap:7px;color:#aaa2bf;font:9px 'DM Mono';letter-spacing:.1em;flex:1}.select-wrap select{width:100%;height:43px;background:#202033;border:1px solid #37364d;border-radius:9px;padding:0 12px;font:12px 'Space Grotesk';color:white}.start-btn{height:43px;padding:0 24px;min-width:145px}
/* Gameplay */
.game-screen{flex:1;min-height:560px;display:flex;flex-direction:column;padding:17px 0 18px}.game-top{height:57px;display:grid;grid-template-columns:50px 1fr 50px;align-items:center;gap:12px}.pause-btn{font-size:17px}.health-wrap{max-width:710px;width:100%;justify-self:center}.health-label{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;font:9px 'DM Mono';letter-spacing:.07em;color:#d4cee8}.health-label b{color:#b4a1f2;letter-spacing:.13em}.healthbar{height:12px;border-radius:20px;background:#3a2638;border:1px solid #ffffff1a;position:relative;overflow:hidden}.health-fill{position:absolute;left:0;top:0;bottom:0;width:50%;background:linear-gradient(90deg,#ff7caa,#b38aff,#66e4dc);transition:width .15s;border-radius:20px}.health-center{position:absolute;left:50%;top:50%;transform:translate(-50%,-54%);font-size:11px;color:#fff;text-shadow:0 0 4px #352a54}.time-chip{font:11px 'DM Mono';text-align:right;color:#c1b6e2}.stage-wrap{position:relative;flex:1;min-height:380px;overflow:hidden;border:1px solid #ffffff13;border-radius:18px;background:#17192a;box-shadow:0 15px 40px #08080f55}.stage-wrap canvas{display:block;width:100%;height:100%}.hud-left,.hud-right{position:absolute;top:14px;display:grid;gap:2px;text-shadow:0 2px 6px #000}.hud-left{left:16px}.hud-right{right:16px;text-align:right}.hud-left b,.hud-right b{font:17px 'DM Mono';color:#fff}.hud-left span,.hud-right span{font:8px 'DM Mono';letter-spacing:.1em;color:#c2bfd0}.combo-hud{position:absolute;left:50%;top:34%;transform:translate(-50%,-50%);font-weight:700;font-size:29px;color:#fff;text-shadow:0 0 17px #9b84ff;pointer-events:none}.combo-hud small{display:block;font:10px 'DM Mono';text-align:center;letter-spacing:.24em;color:#bfb5df}.touch-controls{position:absolute;display:none;left:50%;transform:translateX(-50%);bottom:10px;gap:8px}.touch-controls button{width:58px;height:54px;border:1px solid #ffffff45;border-radius:13px;background:#282740d9;color:#fff;font-size:22px;touch-action:none;box-shadow:0 4px 0 #11111b}.touch-controls button:active,.touch-controls button.hit{transform:translateY(3px);box-shadow:none;background:#8068d5}.game-bottom{height:25px;display:flex;gap:12px;align-items:center;color:#aaa4bd;font:9px 'DM Mono';letter-spacing:.08em}.progress-track{height:4px;background:#363448;border-radius:5px;flex:1}.progress-track i{height:100%;display:block;width:0;background:linear-gradient(90deg,var(--violet),var(--cyan));border-radius:5px}.modal-layer{position:fixed;inset:0;z-index:10;background:#090913c9;display:grid;place-items:center;padding:20px;backdrop-filter:blur(8px)}.modal{width:min(440px,100%);background:#1b1b2d;border:1px solid #50476b;border-radius:20px;padding:27px;box-shadow:0 20px 90px #0009;text-align:center}.modal h2{font-size:27px;margin:8px 0}.modal p{color:#aaa7bc;font-size:13px;line-height:1.6}.modal .primary{margin-top:12px}.modal-actions{display:flex;justify-content:center;gap:9px;flex-wrap:wrap}.settings-grid{display:grid;gap:13px;text-align:left;margin:18px 0}.settings-grid label{display:grid;gap:7px;font:10px 'DM Mono';color:#bab4d0}.settings-grid input{width:100%;accent-color:#a386ff}.result-stat{display:flex;justify-content:center;gap:23px;margin:20px 0}.result-stat b{display:block;font:20px 'DM Mono';color:var(--cyan)}.result-stat small{font:9px 'DM Mono';color:#aaa}
@media(max-width:760px){.app{padding:0 4%}.topbar{height:61px}.menu-screen{grid-template-columns:1fr}.hero-copy{padding:43px 0 12px}.hero-copy h1{font-size:clamp(39px,10vw,59px)}.hero-art{height:285px;grid-row:2;margin:5px 0 20px}.hero-char{transform:scale(.82);transform-origin:bottom}.lup-hero{left:13%;transform:scale(.82) rotate(-4deg)}.calm-hero{right:9%;transform:scale(.82) rotate(4deg)}.menu-lower{grid-column:1}.mode-cards{grid-template-columns:1fr}.mode-card{padding:11px}.foot{font-size:7px}.setup-head{gap:10px;flex-wrap:wrap}.setup-head h1{font-size:31px}.setup-grid{grid-template-columns:1fr;gap:11px}.pick-panel{padding:12px}.roster{grid-template-columns:repeat(4,1fr);max-height:184px}.roster-card{min-height:78px}.mini-avatar{width:32px;height:32px}.setup-footer{flex-wrap:wrap}.select-wrap{min-width:42%}.start-btn{width:100%}.setup-screen{padding:20px 0}.game-screen{min-height:0;height:calc(100dvh - 106px);padding:10px 0}.stage-wrap{min-height:0}.touch-controls{display:flex}.game-top{height:48px}.health-label{font-size:7px}.healthbar{height:10px}.game-bottom{height:19px;font-size:7px}.hud-left,.hud-right{top:8px}.hud-left b,.hud-right b{font-size:13px}.hud-left span,.hud-right span{font-size:7px}.combo-hud{top:27%;font-size:24px}}
@media(max-height:500px) and (orientation:landscape){.app{padding:0 3%}.topbar{height:43px}.game-screen{height:calc(100dvh - 82px);padding:5px 0}.game-top{height:40px}.stage-wrap{min-height:0}.game-bottom{height:16px}.touch-controls{bottom:5px;gap:7px}.touch-controls button{width:56px;height:46px}.hero-copy{padding-top:32px}.hero-art{height:250px}.menu-lower{padding-top:12px}.setup-screen{padding-top:10px}.setup-grid{gap:10px}.pick-panel{padding:10px}.roster-card{min-height:74px}.roster{max-height:190px}.setup-footer{margin-top:10px}}

(() => {
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const cast=[
 {name:'Lupinox',series:'1LUPINOX',icon:'🐺',color:'#55c8e8',kind:'lupinox'},{name:'Calma',series:'1LUPINOX',icon:'🦊',color:'#ff9a57',kind:'calma'},{name:'Boyfriend',series:'FNF',icon:'🧢',color:'#65aaff'},{name:'Girlfriend',series:'FNF',icon:'💗',color:'#f06ba9'},{name:'Pico',series:'FNF',icon:'🔫',color:'#9cdd70'},{name:'Daddy Dearest',series:'FNF',icon:'🎤',color:'#bf75fa'},{name:'Sueños',series:'SUEÑOS',icon:'☁️',color:'#79b8f5'},{name:'Supermúsico',series:'SUPERMÚSICOS',icon:'🎸',color:'#f5d365'},{name:'Duende',series:'LOS DUENDES',icon:'🍄',color:'#8dd677'},{name:'Maga',series:'MAGIA',icon:'✨',color:'#bd86ff'},{name:'Lobo',series:'2 LOBOS MUY MUY ESTÚPIDOS',icon:'🐾',color:'#b6c4df'},{name:'Fuera de casa',series:'FUERA DE CASA',icon:'🏠',color:'#fd956d'},{name:'Modelo roto',series:'MODELOS 3D: ANIMACIÓN DEFECTUOSA',icon:'🧊',color:'#66d9ca'},{name:'NEPT',series:'NEPT - NO ES PARA TODOS',icon:'🪐',color:'#ff7a91'},{name:'Nube',series:'NUBES',icon:'🌥️',color:'#a7b3ff'},{name:'Viajero',series:'OTRAS SERIES',icon:'🌟',color:'#edb569'}
];
const songs=[['Noche de píxeles',118,'#523d85'],['Sueño despierto',104,'#28657a'],['Duelo lunar',132,'#762d68'],['Fuera de órbita',145,'#344884'],['Ritmo defectuoso',124,'#597345'],['Supernova de barrio',110,'#874d38']];
let player=0,opponent=2,mode='free',active=false,paused=false,raf=0,startAt=0,pauseAt=0,elapsed=0,notes=[],score=0,combo=0,best=0,misses=0,judged=0,accuracy=1,health=.5,audio=null,beatTimer=null,musicVol=.45,voiceVol=.65,sfxVol=.65,offset=0,held=new Set(),lastFrame=0;
const lanes=['◀','▼','▲','▶'], laneColors=['#67d9ff','#a687ff','#ff82bd','#ffcd70'];
function fillRoster(id,selected,isOpponent){const box=$(id);box.innerHTML='';box.classList.toggle('opponent-roster',isOpponent);cast.forEach((c,i)=>{const b=document.createElement('button');b.className='roster-card'+(i===selected?' selected':'');b.innerHTML=`<span class="mini-avatar" style="--avatar:${c.color}">${c.icon}</span><b>${c.name}</b><small>${c.series}</small>`;b.onclick=()=>{if(isOpponent)opponent=i;else player=i;fillRoster('#playerRoster',player,false);fillRoster('#opponentRoster',opponent,true)};box.append(b)})}
function setup(which='free'){mode=which;$('#menu').classList.add('hidden');$('#game').classList.add('hidden');$('#setup').classList.remove('hidden');$('#modeLabel').textContent=which==='story'?'MODO HISTORIA':which==='practice'?'PRÁCTICA':'JUEGO LIBRE';fillRoster('#playerRoster',player,false);fillRoster('#opponentRoster',opponent,true);$('#songSelect').innerHTML=songs.map((s,i)=>`<option value="${i}">${s[0]} · ${s[1]} BPM</option>`).join('');if(which==='story'){player=0;opponent=1;fillRoster('#playerRoster',player,false);fillRoster('#opponentRoster',opponent,true);$('#songSelect').value='0'}}
$('#playNow').onclick=()=>setup();$('#storyBtn').onclick=()=>setup('story');$$('.mode-card').forEach(b=>b.onclick=()=>setup(b.dataset.mode));$('#rosterLink').onclick=()=>setup();$('#backMenu').onclick=()=>{$('#setup').classList.add('hidden');$('#menu').classList.remove('hidden')};
function modal(html){$('#modalContent').innerHTML=html;$('#modalLayer').classList.remove('hidden')}function closeModal(){$('#modalLayer').classList.add('hidden')}
function settings(){modal(`<p class="eyebrow">AJUSTA TU EXPERIENCIA</p><h2>Opciones</h2><div class="settings-grid"><label>MÚSICA <input id="musicSlider" type="range" min="0" max="100" value="${musicVol*100}"></label><label>VOCES <input id="voiceSlider" type="range" min="0" max="100" value="${voiceVol*100}"></label><label>EFECTOS <input id="sfxSlider" type="range" min="0" max="100" value="${sfxVol*100}"></label><label>CALIBRACIÓN DE AUDIO <input id="offsetSlider" type="range" min="-150" max="150" value="${offset}"><small id="offsetText">${offset} ms</small></label><label>SENSIBILIDAD TÁCTIL <input id="touchSlider" type="range" min="70" max="150" value="100"></label><label><span>GRÁFICOS</span><select id="quality"><option>Alto</option><option>Equilibrado</option><option>Ligero</option></select></label></div><div class="modal-actions"><button class="primary" id="settingsDone">LISTO</button></div>`);$('#musicSlider').oninput=e=>musicVol=e.target.value/100;$('#voiceSlider').oninput=e=>voiceVol=e.target.value/100;$('#sfxSlider').oninput=e=>sfxVol=e.target.value/100;$('#offsetSlider').oninput=e=>{offset=+e.target.value;$('#offsetText').textContent=offset+' ms'};$('#settingsDone').onclick=closeModal}
$('#settingsOpen').onclick=settings;
const canvas=$('#stage'),ctx=canvas.getContext('2d');let W=1000,H=600,dpr=1;
function resize(){if(!canvas.isConnected)return;const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;dpr=Math.min(devicePixelRatio||1,2);canvas.width=r.width*dpr;canvas.height=r.height*dpr;W=r.width;H=r.height;ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(canvas);
function start(){closeModal();$('#setup').classList.add('hidden');$('#menu').classList.add('hidden');$('#game').classList.remove('hidden');active=true;paused=false;score=combo=best=misses=judged=0;accuracy=1;health=.5;elapsed=0;held.clear();const song=songs[+$('#songSelect').value],diff=$('#difficulty').value,bpm=song[1]*(diff==='Experto'?1.12:diff==='Fácil'?.9:1);const beat=60/bpm,total=64*beat;notes=[];for(let n=2;n<64;n++){if(Math.random()<(diff==='Fácil'?.60:.79)){let lane=(n*7+Math.floor(n/3))%4;let type=(n%13===0?'special':n%9===0?'hold':n%7===0?'fast':'normal');notes.push({t:n*beat,lane,type,hit:false,missed:false});if(n%11===5)notes.push({t:n*beat,lane:(lane+1)%4,type:'normal',hit:false,missed:false})}}notes.sort((a,b)=>a.t-b.t);notes.total=total;$('#playerNameHud').textContent=cast[player].name.toUpperCase();$('#opponentNameHud').textContent=cast[opponent].name.toUpperCase();$('#songHud').textContent=song[0].toUpperCase();$('#difficultyHud').textContent=diff.toUpperCase();startAt=performance.now();lastFrame=startAt;initAudio();startBacking(bpm);resize();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}$('#startGame').onclick=start;
function initAudio(){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch(e){audio=null}}
function tone(freq,duration,wave='sine',vol=.12,slide=0){if(!audio)return;const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=wave;o.frequency.setValueAtTime(freq,now);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),now+duration);g.gain.setValueAtTime(Math.max(.001,vol),now);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+duration)}function kick(){tone(100,.16,'sine',musicVol*.27,-65)}function tick(){if(!active||paused)return;const beat=60/(songs[+$('#songSelect').value][1]*(($('#difficulty').value==='Experto')?1.12:($('#difficulty').value==='Fácil'?.9:1)));const ix=Math.round(elapsed/beat);if(ix%4===0)kick();else tone(ix%2?1700:1100,.035,'square',musicVol*.035);if(ix%4===2)tone(170,.12,'triangle',musicVol*.11,-35);const scale=[0,3,5,7,10][ix%5],freq=196*Math.pow(2,scale/12);if(ix%2===0)tone(freq,.22,'triangle',musicVol*.09);beatTimer=setTimeout(tick,beat*1000)}function startBacking(){clearTimeout(beatTimer);tick()}
function vocal(lane,quality='normal'){const base=[220,261.6,329.6,392][lane];tone(base*(player===1?1.25:1),quality==='hold'?.24:.12,player===0?'sawtooth':player===2?'square':'triangle',voiceVol*(quality==='special'?.2:.12),quality==='special'?90:0);if(quality==='special')tone(base*2,.15,'sine',voiceVol*.1)}
